:root{--g:#21633f;--dark:#17492f;--p:#eaf2df;--bg:#f8f8f3;--ink:#202820;--mut:#7d857b;--line:#e9ece5}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);font-family:'DM Sans',sans-serif;color:var(--ink)}
button{font:inherit;cursor:pointer}
/* loading */
.loading{position:fixed;inset:0;background:var(--bg);display:grid;place-items:center;z-index:30;transition:.45s}
.loading.hide{opacity:0;visibility:hidden}
.loadbox{text-align:center}
.loadlogo{margin:0 auto 14px;width:72px;height:72px;background:var(--g);border-radius:22px;display:grid;place-items:center;box-shadow:0 12px 28px #21633f33}
.loadlogo svg{width:44px}
.loadbox b{font:800 23px 'Plus Jakarta Sans';letter-spacing:-.5px}
.loadbox p{color:var(--mut);font-size:10px;letter-spacing:1.4px;margin:5px 0 0}
.bar{width:125px;height:4px;background:#e3e9df;border-radius:8px;margin:22px auto 0;overflow:hidden}
.bar i{display:block;width:50%;height:100%;background:var(--g);border-radius:8px;animation:go .9s infinite alternate}
@keyframes go{to{transform:translateX(125px)}}
/* topbar */
.top{height:72px;background:white;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 max(calc((100vw - 1100px)/2),5%);gap:40px;position:sticky;top:0;z-index:4}
.brand{display:flex;align-items:center;gap:10px}
.logo{width:42px;height:42px;border-radius:14px;background:var(--g);color:white;display:grid;place-items:center;flex:none}
.logo svg{width:26px}
.brand b{font:800 18px 'Plus Jakarta Sans';letter-spacing:-.7px;text-transform:lowercase}
.brand small{display:block;font-size:9px;letter-spacing:1.3px;color:#879084}
.nav{height:100%;display:flex;gap:25px}
.nav button{border:0;background:none;color:var(--mut);font-weight:700;font-size:12px;position:relative;padding:0}
.nav button.on{color:var(--g)}
.nav button.on:after{content:'';position:absolute;bottom:0;left:0;right:0;height:3px;background:var(--g);border-radius:4px}
.topright{margin-left:auto;display:flex;align-items:center;gap:14px;color:var(--mut);font-size:12px}
.bag{background:var(--g);color:white;border:0;border-radius:11px;padding:10px 13px;font-weight:700;display:flex;align-items:center;gap:7px}
.bag:hover{background:var(--dark)}
.count{padding:2px 7px;border-radius:20px;background:#fff;color:var(--g);font-size:11px}
.main{max-width:1080px;margin:auto;padding:30px 22px 80px}
.view{display:none}
.view.on{display:block}
/* hero */
.hero{position:relative;overflow:hidden;background:var(--g);color:#fff;border-radius:23px;padding:36px 46px;min-height:235px;display:flex;align-items:center}
.hero:after{content:'';position:absolute;width:320px;height:320px;border:1px solid #ffffff26;border-radius:50%;right:60px;top:-50px;box-shadow:0 0 0 34px #ffffff0d,0 0 0 68px #ffffff08}
.eyebrow{font-size:10px;letter-spacing:2px;color:#d9edb7;font-weight:800;text-transform:uppercase}
.hero h1{font:800 37px/1.18 'Plus Jakarta Sans';letter-spacing:-1.4px;margin:12px 0}
.hero p{font-size:12px;color:#e0ebdf;margin:0;line-height:1.7;max-width:430px}
.deal{display:inline-block;margin-top:16px;padding:8px 13px;border-radius:20px;background:#ffffff1f;border:1px solid #ffffff2e;font-size:10px;font-weight:600}
.heroart{position:absolute;right:115px;top:50%;transform:translateY(-50%);font-size:92px;z-index:1;filter:drop-shadow(0 12px 9px #102d1c66)}
/* menu */
.welcome{display:flex;justify-content:space-between;align-items:end;margin:31px 0 16px}
.welcome h2{font:800 21px 'Plus Jakarta Sans';margin:0 0 5px;letter-spacing:-.5px}
.welcome p{font-size:12px;color:var(--mut);margin:0}
.search{height:41px;width:240px;background:white;border:1px solid var(--line);border-radius:11px;display:flex;align-items:center;padding:0 13px;gap:8px;color:#8a9088}
