.cats{display:flex;gap:9px;overflow:auto;padding:3px 0 18px;scrollbar-width:none}
.cat{white-space:nowrap;padding:9px 15px;border:1px solid var(--line);border-radius:20px;background:white;color:#687167;font-size:11px;font-weight:700}
