.cat.on{background:var(--g);color:white;border-color:var(--g)}
.sect{display:flex;justify-content:space-between;align-items:center;margin:8px 0 14px}
.sect h3{font:800 16px 'Plus Jakarta Sans';margin:0;letter-spacing:-.3px}
.sect span{font-size:11px;color:var(--mut)}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}
.card{border:1px solid #edf0e9;border-radius:16px;background:white;overflow:hidden;transition:.2s}
.card:hover{transform:translateY(-3px);box-shadow:0 10px 26px #173c2014}
.photo{height:138px;display:grid;place-items:center;position:relative;background:linear-gradient(135deg,#f5efdf,#e7ecd9)}
.photo:before{content:'';position:absolute;width:100px;height:100px;border-radius:50%;background:#fff9;box-shadow:0 5px 14px #53421b20}
.emoji{font-size:62px;z-index:1;filter:drop-shadow(0 7px 4px #4a351b22)}
