.price{font-size:12.5px;font-weight:800;color:var(--g)}
.add{height:30px;width:30px;border:0;border-radius:9px;background:var(--p);color:var(--g);font-size:19px;line-height:1}
.add:hover{background:var(--g);color:white}
.features{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:24px}
.feature{display:flex;align-items:center;gap:12px;background:white;border:1px solid var(--line);border-radius:14px;padding:15px}
.fi{width:39px;height:39px;border-radius:11px;background:var(--p);display:grid;place-items:center;font-size:19px;flex:none}
.feature b{font-size:11.5px}
.feature p{font-size:10px;color:var(--mut);margin:4px 0 0}
/* checkout */
.title{margin:12px 0 20px}
.title h1{font:800 26px 'Plus Jakarta Sans';margin:0 0 5px;letter-spacing:-.7px}
.title p{font-size:12px;color:var(--mut);margin:0}
.cols{display:grid;grid-template-columns:1.3fr .8fr;gap:20px;align-items:start}
.panel{background:white;border:1px solid var(--line);border-radius:16px;padding:20px;margin-bottom:14px}
.panel h3{font:800 14px 'Plus Jakarta Sans';margin:0 0 15px;letter-spacing:-.3px}
.row{display:flex;align-items:center;gap:12px;padding:11px 0;border-bottom:1px solid #f0f1ed}
.row:last-child{border-bottom:0}
.thumb{width:50px;height:50px;display:grid;place-items:center;border-radius:11px;background:#f3f0e7;font-size:26px;flex:none}
.rowinfo{flex:1;min-width:0}
.rowinfo b{font-size:11.5px}
.rowinfo small{display:block;font-size:10px;color:var(--mut);margin-top:4px}
.qty{display:flex;align-items:center;gap:8px;font-size:11px;font-weight:700}
.qty button{border:1px solid var(--line);border-radius:7px;background:white;color:var(--g);width:25px;height:25px;font-size:14px;line-height:1}
.qty button:hover{background:var(--g);color:white;border-color:var(--g)}
.pay{display:flex;align-items:center;gap:11px;border:1px solid var(--line);border-radius:11px;padding:12px;margin:8px 0;cursor:pointer;font-size:17px;transition:.15s}
.pay.selected{border-color:var(--g);background:#f5f9f1}
.pay input{accent-color:var(--g);margin:0}
.pay b{font-size:11.5px}
.pay small{display:block;color:var(--mut);font-size:9.5px;margin-top:3px}
.sum{display:flex;justify-content:space-between;color:#72796f;font-size:11.5px;margin:12px 0}
.sum b{color:var(--ink)}
.sum.total{padding-top:13px;border-top:1px solid var(--line);font-size:14.5px;color:var(--ink);font-weight:800}
.primary{border:0;background:var(--g);color:white;width:100%;border-radius:11px;padding:13px;font-size:12.5px;font-weight:800;margin-top:6px}
.primary:hover{background:var(--dark)}
.primary:disabled{background:#b9c4ba;cursor:not-allowed}
.empty{text-align:center;padding:40px 12px;color:var(--mut);font-size:12px}
.empty span{font-size:40px;display:block}
.empty strong{display:block;color:var(--ink);font:800 16px 'Plus Jakarta Sans';margin:10px 0 5px}
.link{border:0;background:none;color:var(--g);font-weight:700;font-size:11.5px;text-decoration:underline;margin-top:8px}
/* history */
.history{display:flex;align-items:center;gap:13px;background:white;border:1px solid var(--line);padding:15px 17px;border-radius:14px;margin-bottom:11px}
.hdetails{flex:1;min-width:0}
.hdetails b{font-size:12.5px}
.hdetails p{margin:4px 0 0;color:var(--mut);font-size:10.5px}
.hdetails small{display:block;margin-top:6px;color:#5d655c;font-size:10px}
.status{flex:none;font-size:9.5px;color:var(--g);font-weight:800;background:var(--p);padding:6px 9px;border-radius:16px}
.htotal{flex:none;font-size:12.5px;font-weight:800;color:var(--g)}
/* toast + mobile nav */
.toast{position:fixed;bottom:25px;left:50%;transform:translate(-50%,20px);opacity:0;transition:.22s;background:#183c27;color:white;border-radius:11px;padding:12px 18px;font-size:12px;z-index:20;pointer-events:none;white-space:nowrap}
.toast.show{opacity:1;transform:translate(-50%,0)}
.mobile{display:none}
