.hero{padding:30px;min-height:220px}.hero h1{font-size:32px}
.heroart{right:35px;font-size:70px}
.cols{grid-template-columns:1fr}.summarycol{order:-1}
}
@media(max-width:540px){
.top{height:62px;padding:0 14px}.brand b{font-size:16px}.nav{display:none}
.main{padding:17px 14px 90px}
.hero{padding:24px 20px;min-height:205px;border-radius:19px}
.hero h1{font-size:28px;max-width:270px}.hero p{font-size:11px}
.heroart{font-size:58px;right:12px;top:auto;bottom:16px;transform:none;opacity:.65}
.welcome{display:block;margin:25px 0 14px}.welcome h2{font-size:19px}
.search{margin-top:13px;width:100%}
.grid{gap:10px}.photo{height:120px}.emoji{font-size:52px}
.features{grid-template-columns:1fr}
.panel{padding:16px}
.htotal{display:none}
.mobile{position:fixed;bottom:0;left:0;right:0;z-index:10;background:white;border-top:1px solid var(--line);height:64px;display:flex;justify-content:space-around;padding-bottom:env(safe-area-inset-bottom)}
.mobile button{border:0;background:none;color:#899087;font-size:9px;font-weight:700;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;min-width:64px}
.mobile button span{font-size:18px}
.mobile button.on{color:var(--g)}
}
