{id:5,n:'Mie Goreng Jawa',cat:'Makanan Berat',em:'🍝',price:21000,old:0,desc:'Mie manis gurih, sayur, telur, taburan bawang goreng.',long:'Mie kuning ditumis kecap manis dengan bumbu kacang dan sedikit petis, disajikan hangat bersama irisan timun dan cabe rawit.',rate:4.6,sold:640,tags:['Tumis'],fav:0,badge:''},
{id:6,n:'Pecel Lele Sambal Terasi',cat:'Makanan Berat',em:'🐟',price:23000,old:0,desc:'Lele goreng kriuk, sambal terasi, lalapan & nasi.',long:'Lele segar dimarinasi kunir-ketumbar lalu digoreng garing, ditemani sambal terasi ulek tangan dan lalapan timun-kemangi.',rate:4.7,sold:720,tags:['Pedas'],fav:0,badge:''},
{id:7,n:'Rendang Daging Sapi',cat:'Makanan Berat',em:'🥘',price:38000,old:45000,desc:'Rendang kering santan kelapa, empuk dan gurih.',long:'Daging sandung lamur dimasak perlahan dengan santan kental dan sebelas jenis rempah hingga menghitam kering, tahan lama dan kaya rasa.',rate:5.0,sold:530,tags:['Premium','Pedas'],fav:1,badge:'Premium'},
{id:8,n:'Sayur Lodeh + Tempe',cat:'Makanan Berat',em:'',price:18000,old:0,desc:'Sayur santan encer, tempe goreng, sambal terasi.',long:'Kacang panjang, labu siam, dan terung dalam kuah santan berbumbu lengkuas, pelengkap sempurna nasi panas dan tempe mendoan.',rate:4.5,sold:410,tags:['Rumah'],fav:0,badge:''},
{id:9,n:'Tempe Mendoan',cat:'Camilan',em:'🥟',price:12000,old:0,desc:'Tempe tipis berbalut tepung bumbu, sambal kecap.',long:'Tempe iris tipis dibalut tepung bercampur daun kucai, digoreng setengah matang agar tetap lembut, dicocol sambal kecap rawit.',rate:4.8,sold:1320,tags:['Camilan'],fav:1,badge:'Favorit'},
{id:10,n:'Tahu Walik Crispy',cat:'Camilan',em:'🧆',price:15000,old:0,desc:'Tahu balik isi aci ayam, 5 pcs per porsi.',long:'Tahu kulit dibalik lalu diisi adonan aci dan suwiran ayam, digoreng dua kali supaya renyah tahan lama. Cocok untuk ngobrol panjang.',rate:4.6,sold:890,tags:['Gorengan'],fav:0,badge:''},
{id:11,n:'Pisang Goreng Madu',cat:'Camilan',em:'🍌',price:14000,old:17000,desc:'Pisang raja renyah, siram madu hutan & keju.',long:'Pisang raja pilihan digoreng dengan tepung tipis, dituang madu hutan Sumbawa dan parutan keju melimpah di atasnya.',rate:4.7,sold:760,tags:['Manis'],fav:0,badge:'Baru'},
