{id:18,n:'Susu Jahe Merah',cat:'Minuman',em:'🫚',price:12000,old:0,desc:'Jahe emprit rebus, madu, perasan jeruk nipis.',long:'Jahe emprit tua digeprek dan direbus lambat bersama kayu manis, diberi madu hutan dan jeruk nipis. Hangat sampai ke tulang.',rate:4.6,sold:610,tags:['Hangat'],fav:0,badge:'']
];
const CATS=['Semua','Makanan Berat','Camilan','Minuman'];
const CAT_IC={'Semua':'🍽️','Makanan Berat':'🍛','Camilan':'🥟','Minuman':'🥤'};
const SPICE=['Tidak pedas','Sedang','Pedas','Nyoss!'];
const ADDONS=['Tanpa tambahan','Telur mata sapi +Rp5.000','Extra nasi +Rp5.000','Sambal extra +Rp3.000'];
const SHIP=8000, FREELIM=75000;
const PROMOS=[
{cls:'brick',ic:'🍗',t:'Diskon 20% Ayam Bakar',s:'Berlaku setiap Senin–Rabu, selama stok ada.',code:'SEDAP20'},
{cls:'amber',ic:'🛵',t:'Gratis Ongkir',s:'Minimal belanja Rp75.000 ke seluruh kota.',code:'ONGKIRGRATIS'},
{cls:'brown',ic:'☕',t:'Beli Kopi, Gratis Mendoan',s:'Tiap Jumat malam, maksimal satu kali per akun.',code:'JUMATSEDAP'}];
const VOUCH={'SEDAP20':20,'NGEMIL10':10};

/* ---------- state ---------- */
const LS=(k,d)=>{try{const v=JSON.parse(localStorage.getItem(k));return v==null?d:v}catch(e){return d}};
const SAVE=()=>{localStorage.setItem('sw-users',JSON.stringify(S.users));localStorage.setItem('sw-session',JSON.stringify(S.session));localStorage.setItem('sw-cart',JSON.stringify(S.cart));localStorage.setItem('sw-orders',JSON.stringify(S.orders))};
let S={
 users:LS('sw-users',[{name:'Pelanggan Wetan',email:'demo@sedepwetan.id',pass:'demo123',phone:'0812-3456-7890',addr:'Jl. Kaliurang KM 5, Sleman, Yogyakarta',joined:'Februari 2024',tier:'Sedep Loyal'}]),
 session:LS('sw-session',null),
 cart:LS('sw-cart',[]),
 orders:LS('sw-orders',[
  {code:'SW240817',date:'17 Agu 2025',time:'19:12',items:[{em:'🍗',n:'Ayam Bakar Taliwang',q:2,price:32000},{em:'🧋',n:'Es Teh Melati Jumbo',q:2,price:8000}],pay:'QRIS',total:80000,status:'Selesai',rated:true},
  {code:'SW240809',date:'9 Agu 2025',time:'12:03',items:[{em:'🍛',n:'Nasi Goreng Kampung',q:1,price:24000},{em:'🥤',n:'Es Dawet Sinting',q:1,price:13000}],pay:'GoPay',total:37000,status:'Selesai',rated:false}
 ]),
 menu:LS('sw-menu',null)||FOODS.map(f=>({...f,on:true})),
 cat:'Semua',q:'',sort:'pop',spicy:'all',voucher:null,
 pay:'QRIS',draft:null,pendingAction:null,tab:'dash',amsg:''
};
if(!localStorage.getItem('sw-menu'))SAVE();

const $=s=>document.querySelector(s);
const $$=s=>[...document.querySelectorAll(s)];
const money=n=>'Rp'+Math.round(n).toLocaleString('id-ID');
const food=id=>S.menu.find(f=>f.id==id);
const cartCount=()=>S.cart.reduce((a,c)=>a+c.q,0);
const linePrice=i=>i.price+(i.addon?+(i.addon.match(/\+Rp([\d.]+)/)||[0,0])[1].replace(/\./g,'')||0:0);
const subTotal=()=>S.cart.reduce((a,i)=>a+linePrice(i)*i.q,0);
const discAmt=s=>Math.round(s*((S.voucher&&VOUCH[S.voucher])||0)/100);
const shipOf=s=>s>=FREELIM||!s?0:SHIP;
const grand=()=>{const s=subTotal();return s-discAmt(s)+shipOf(s)};
const initials=n=>n.trim().split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase();
const loggedIn=()=>!!S.session;

/* ---------- toast ---------- */
let tt;function toast(m){const t=$('#toast');t.innerHTML='🌿 '+m;t.classList.add('show');clearTimeout(tt);tt=setTimeout(()=>t.classList.remove('show'),2300)}

/* ---------- router ---------- */
const VIEWS=['home','menu','auth','checkout','payment','orders','profile','about','admin'];
function go(v,force){
  if(!force&&!loggedIn()&&['checkout','payment','orders','profile'].includes(v))return requireLogin(v);
  $$('.view').forEach(s=>s.classList.toggle('on',s.id==='v-'+v));
  $$('#nav button,#mobnav button').forEach(b=>b.classList.toggle('on',b.dataset.v===v));
  if(v==='home')renderHome();
  if(v==='menu')renderMenu();
  if(v==='auth')renderAuth();
  if(v==='checkout')renderCheckout();
  if(v==='payment')renderPayment();
  if(v==='orders')renderOrders();
  if(v==='profile')renderProfile();
  if(v==='about')renderAbout();
  if(v==='admin')renderAdmin();
  $('#foot').style.display=v==='auth'?'none':'block';
  window.scrollTo({top:0,behavior:'smooth'});
}
function requireLogin(next){
  S.pendingAction=next||'checkout';
  go('auth',true);
  toast('Login dulu ya, supaya pesananmu bisa terlacak 🙏');
  return false;
}
function openCart(){loggedIn()?go('checkout'):requireLogin('checkout')}

/* ---------- auth zone in header ---------- */
function renderAuthZone(){
  $('#authzone').innerHTML=loggedIn()
   ? `<button class="userchip" onclick="go('profile')"><span class="avatar">${initials(S.session.name)}</span>${S.session.name.split(' ')[0]}</button>`
   : `<button class="btn btn-o btn-s" onclick="go('auth',true)">Masuk</button><button class="btn btn-p btn-s" onclick="regMode()">Daftar</button>`;
}
function regMode(){AUTH.mode='register';go('auth',true)}

/* ---------- cards ---------- */
function fcard(f){
  const badge=f.badge?`<span class="ftag ${f.badge==='Baru'?'new':''}">${f.badge}</span>`:'';
  return `<article class="fcard">
    <div class="fph" onclick="detail(${f.id})" style="cursor:pointer">${badge}<span class="em">${f.em}</span></div>
    <div class="fbody">
      <h4 onclick="detail(${f.id})" style="cursor:pointer">${f.n}</h4>
      <div class="fdesc">${f.desc}</div>
      <div class="fmeta"><span class="frate">★ ${f.rate.toFixed(1)}</span><span>· ${f.sold.toLocaleString('id-ID')} terjual</span></div>
      <div class="fbot">
        <span class="fprice">${money(f.price)}${f.old?`<s>${money(f.old)}</s>`:''}</span>
        <button class="plus" title="Tambah ke keranjang" onclick="addToCart(${f.id})">+</button>
      </div>
    </div></article>`;
}
function addToCart(id){
  if(!loggedIn())return requireLogin('menu');
  detail(id,true);
}
function quickAdd(id){
  if(!loggedIn())return requireLogin('menu');
  const f=food(id);
  const ex=S.cart.find(i=>i.id===id&&i.spice==='Sedang'&&i.addon==='Tanpa tambahan');
  if(ex)ex.q++;else S.cart.push({id,n:f.n,em:f.em,price:f.price,q:1,spice:'Sedang',addon:'Tanpa tambahan'});
  SAVE();badgeUp();toast(`${f.n} masuk keranjang 🛍`);
}
function badgeUp(){$('#cbadge').textContent=cartCount()}

/* ---------- home ---------- */
function renderHome(){
  $('#hero').innerHTML=`<div class="hero"><div class="heroin">
    <span class="eyebrow">🌿 Dapur terbuka tiap hari 09.00–22.00</span>
    <h1>Rasa rumahan,<br>bikin kangen.</h1>
    <p>Masakan Indonesia hangat dengan resep pilihan keluarga. Dibuat segar setiap hari, khusus untuk kamu yang rindu masakan rumah.</p>
    <div class="heroact">
      <button class="btn btn-a" onclick="go('menu')">Pesan Sekarang →</button>
      <button class="btn btn-g" onclick="go('about')">Tentang Kami</button>
    </div></div>
    <div class="herostat"><div class="splate">🍲</div>
      <div class="chipstat">⭐ 4,9 · 2.300+ ulasan</div>
      <div class="chipstat">🛵 Diantar 20–35 menit</div>
    </div></div>`;
  $('#promos').innerHTML=PROMOS.map(p=>`<div class="promo ${p.cls}"><em>${p.ic}</em><b>${p.t}</b><span>${p.s}</span><code>${p.code}</code></div>`).join('');
  const favs=S.menu.filter(f=>f.fav&&f.on);
  $('#favCount').textContent=favs.length+' menu pilihan';
  $('#favs').innerHTML=favs.map(f=>fcard(f)).join('');
  $('#homeGrid').innerHTML=S.menu.filter(f=>f.on).slice(0,8).map(f=>fcard(f)).join('');
  $('#homeVals').innerHTML=`<div class="vals">
   <div class="val"><i>🌱</i><b>Bahan segar pasar lokal</b><p>Sayur, bumbu, dan daging dipilih pagi hari agar mutu terjaga.</p></div>
   <div class="val"><i></i><b>Resep turun-temurun</b><p>Bumbu yang sama sejak warung kecil di sisi timur kota tahun 1998.</p></div>
   <div class="val"><i>🛵</i><b>Diantar penuh hati</b><p>Kurir internal, kemasan kedap, pesanan tiba hangat dan utuh.</p></div></div>`;
}

/* ---------- menu ---------- */
function renderCats(){
  $('#cats').innerHTML=CATS.map(c=>`<button class="cat ${S.cat===c?'on':''}" onclick="S.cat='${c}';renderMenu()"><i>${CAT_IC[c]}</i>${c}</button>`).join('');
}
function toggleSpicy(){
  const order=['all','Tidak pedas','Sedang','Pedas','Nyoss!'];
  S.spicy=order[(order.indexOf(S.spicy)+1)%order.length];
  $('#spicyBtn').textContent=S.spicy==='all'?'🌶 Semua level':'🌶 '+S.spicy;
  renderMenu();
}
function filtered(){
  let l=S.menu.filter(f=>f.on&&(S.cat==='Semua'||f.cat===S.cat)&&(f.n+' '+f.desc+' '+f.tags.join(' ')).toLowerCase().includes(S.q.toLowerCase()));
  if(S.spicy!=='all'){const idx=SPICE.indexOf(S.spicy);l=l.filter(f=>f.tags.includes('Pedas')?idx>=1:idx<=1)}
  const s={lo:(a,b)=>a.price-b.price,hi:(a,b)=>b.price-a.price,az:(a,b)=>a.n.localeCompare(b.n),rate:(a,b)=>b.rate-a.rate,pop:(a,b)=>b.sold-a.sold}[S.sort];
  return [...l].sort(s);
}
function renderMenu(){
  renderCats();
  const l=filtered();
  $('#mTitle').textContent=S.cat==='Semua'?'Semua menu':S.cat;
  $('#mCount').textContent=l.length+' menu ditemukan';
  $('#mGrid').innerHTML=l.map(f=>fcard(f)).join('')||`<div class="empty" style="grid-column:1/-1"><span class="em">🔍</span><b>Menu tidak ditemukan</b>Coba kata kunci atau kategori lain.</div>`;
}

/* ---------- product detail ---------- */
let DET={};
function detail(id,quick){
  const f=food(id);DET={id,qty:1,spice:'Sedang',addon:'Tanpa tambahan'};
  $('#modalBox').innerHTML=`<button class="mclose" onclick="closeModal()">✕</button>
  <div class="pdet">
    <div class="pdimg"><span class="em">${f.em}</span></div>
    <div class="pdbody">
      <span class="eyebrow">${f.cat} ${f.badge?'· '+f.badge:''}</span>
      <h2>${f.n}</h2>
      <div class="stars"><b>★ ${f.rate.toFixed(1)}</b><span>· ${f.sold.toLocaleString('id-ID')} terjual · 20–35 menit</span></div>
      <p class="pdesc">${f.long}</p>
      <div class="fmeta" style="font-size:11.5px">${f.tags.map(t=>`<span class="chip" style="pointer-events:none">${t==='Pedas'?'🌶 ':t==='Manis'?'🍯 ':t==='Kuah'?'🍲 ':''}${t}</span>`).join('')}</div>
      <div class="opttl">Level pedas</div>
      <div class="spice">${SPICE.map(s=>`<button class="${s===DET.spice?'on':''}" onclick="setSpice(this,'${s}','${f.tags.includes('Pedas')}")">${s}</button>`).join('')}</div>
      <div class="opttl">Tambahan</div>
      <div class="chips">${ADDONS.map(a=>`<button class="chip ${a===DET.addon?'on':''}" onclick="setAddon(this,'${a}')">${a}</button>`).join('')}</div>
      <div class="qtyrow">
        <div class="stepper"><button onclick="stepQty(-1)">−</button><span id="dqty">1</span><button onclick="stepQty(1)">+</button></div>
        <span class="muted small">Jumlah porsi</span>
      </div>
      <div class="pfoot">
        <div><span class="tp" id="dtotal">${money(f.price)}</span><small>sudah termasuk pajak</small></div>
        <button class="btn btn-p" id="dadd" onclick="confirmAdd()">🛍 Tambah ke keranjang</button>
      </div>
    </div>
  </div>`;
  $('#modal').classList.add('on');
  document.body.style.overflow='hidden';
  if(quick)toast('Atur dulu level pedas & tambahannya ya 🌶');
}
function setSpice(el,s){DET.spice=s;$$('.spice button').forEach(b=>b.classList.toggle('on',b.textContent.trim()===s))}
function setAddon(el,a){DET.addon=a;$$('.chips .chip').forEach(b=>b.classList.toggle('on',b.textContent.replace(' ✓','')===a));recalc()}
function stepQty(d){DET.qty=Math.max(1,DET.qty+d);$('#dqty').textContent=DET.qty;recalc()}
function recalc(){const f=food(DET.id);$('#dtotal').textContent=money(linePrice({price:f.price,addon:DET.addon})*DET.qty)}
function confirmAdd(){
  if(!loggedIn()){closeModal();return requireLogin('menu')}
  const f=food(DET.id);
  const item={id:f.id,n:f.n,em:f.em,price:f.price,q:DET.qty,spice:DET.spice,addon:DET.addon};
  const ex=S.cart.find(i=>i.id===f.id&&i.spice===DET.spice&&i.addon===DET.addon);
  if(ex)ex.q+=DET.qty;else S.cart.push(item);
  SAVE();badgeUp();closeModal();
  toast(`${f.n} ×${DET.qty} masuk keranjang 🛍`);
}
function closeModal(){$('#modal').classList.remove('on');document.body.style.overflow=''}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});

/* ---------- auth ---------- */
let AUTH={mode:'login'};
function renderAuth(){
  const r=AUTH.mode==='register';
  $('#authWrap').innerHTML=`<div class="auth">
    <div class="authside"><span class="em">🍲</span>
      <span class="eyebrow" style="color:var(--amber-l)">Selamat datang</span>
      <h2>${r?'Satu akun,<br>segudang rasa rumahan.':'Kangen masakan<br>rumah lagi?'}</h2>
      <p>Masuk untuk menyimpan favorit, melacak pesanan, dan mengecek riwayat transaksi kapan saja.</p>
      <div class="authlist">
        <div><i>🛵</i>Lacak pesanan real-time</div>
        <div><i>❤️</i>Simpan menu favorit di satu tempat</div>
        <div><i>🎟️</i>Kumpulkan poin & voucher pelanggan lama</div>
      </div></div>
    <div class="authmain"><div class="authbox">
      <button class="brand" onclick="go('home',true)"><span class="logo sm" data-logo></span><span class="brandtxt"><b>sedep wetan</b></span></button>
      <h1>${r?'Buat akun baru':'Masuk ke akunmu'}</h1>
      <p>${r?'Isi data singkat, langsung bisa memesan.':'Halo lagi! Silakan masuk untuk lanjut memesan.'}</p>
      <div class="err" id="authErr"></div>
      ${r?`<div class="field"><label>Nama lengkap</label><input class="inp" id="fName" placeholder="Misal: Sekar Ayu"></div>`:''}
      <div class="field"><label>Email</label><input class="inp" id="fEmail" type="email" placeholder="nama@email.com"></div>
      ${r?`<div class="field"><label>No. WhatsApp</label><input class="inp" id="fPhone" placeholder="08xxxxxxxxxx"></div>`:''}
      <div class="field"><label>Kata sandi</label><div class="inpw"><input class="inp" id="fPass" type="password" placeholder="${r?'Minimal 6 karakter':'••••••••'}"><button onclick="peek('fPass',this)">👁</button></div></div>
      ${r?`<div class="field"><label>Alamat pengiriman</label><textarea class="ta" id="fAddr" placeholder="Jalan, nomor, kelurahan, kota"></textarea></div>
      <div class="frow"><label><input type="checkbox" class="chk" id="fAgree">Saya setuju dengan syarat &amp; kebijakan privasi</label></div>`
      :`<div class="frow"><label><input type="checkbox" class="chk">Ingat saya</label><a href="#" onclick="toast('Cek email kamu untuk tautan reset 🔑');return false">Lupa sandi?</a></div>`}
      <button class="btn btn-p btn-f" onclick="submitAuth()">${r?'Buat akun & mulai pesan':'Masuk'}</button>
      <div class="divider">atau</div>
      <div class="social"><button class="btn btn-o" onclick="social('Google')">G&nbsp; Google</button><button class="btn btn-o" onclick="social('WhatsApp')">💬 WhatsApp</button></div>
      <div class="swap">${r?'Sudah punya akun?':'Belum punya akun?'}<button onclick="AUTH.mode='${r?'login':'register'}';renderAuth()">${r?'Masuk di sini':'Daftar sekarang'}</button></div>
      <div class="demo">🔑 <b>Akun demo:</b> demo@sedepwetan.id / demo123 — atau klik tombol di bawah.<br>
        <button class="btn btn-o btn-s" style="margin-top:9px" onclick="demoLogin()">Masuk pakai akun demo</button></div>
    </div></div></div>`;
  $$('[data-logo]').forEach(e=>e.innerHTML=LEAF);
}
function peek(id,btn){const i=$('#'+id);i.type=i.type==='password'?'text':'password';btn.textContent=i.type==='password'?'👁':''}
function authErr(m){const e=$('#authErr');e.textContent='⚠ '+m;e.classList.add('on')}
function submitAuth(){
  const email=$('#fEmail').value.trim().toLowerCase(),pass=$('#fPass').value;
  if(AUTH.mode==='login'){
    const u=S.users.find(x=>x.email.toLowerCase()===email);
    if(!u)return authErr('Email belum terdaftar. Coba daftar dulu, ya.');
    if(u.pass!==pass)return authErr('Kata sandi salah. Periksa kembali.');
    login(u);
  }else{
    const name=$('#fName').value.trim(),phone=$('#fPhone').value.trim(),addr=$('#fAddr').value.trim();
    if(name.length<3)return authErr('Nama lengkap minimal 3 karakter.');
    if(!/^\S+@\S+\.\S+$/.test(email))return authErr('Format email belum benar.');
    if(S.users.some(x=>x.email.toLowerCase()===email))return authErr('Email sudah dipakai. Silakan masuk.');
    if(pass.length<6)return authErr('Kata sandi minimal 6 karakter.');
    if(!$('#fAgree').checked)return authErr('Centang persetujuan syarat & ketentuan.');
    const u={name,email,pass,phone:phone||'-',addr:addr||'-',joined:new Date().toLocaleDateString('id-ID',{month:'long',year:'numeric'}),tier:'Pendatang Baru'};
    S.users.push(u);login(u);
  }
}
function social(p){
  const u=S.users[0];login(u,`${p} Connect (simulasi)`);
}
function demoLogin(){login(S.users[0],'Akun demo')}
function login(u,label){
  S.session={name:u.name,email:u.email,phone:u.phone,addr:u.addr,joined:u.joined,tier:u.tier};
  SAVE();renderAuthZone();
  toast(`Sugeng rawuh, ${u.name.split(' ')[0]}! ${label?'('+label+')':''} 👋`);
  const back=S.pendingAction;S.pendingAction=null;
  if(back==='menu'||back==='checkout'){go('menu');}
  else if(back==='orders'||back==='profile'||back==='payment')go(back);
  else go('home',true);
  if(back==='checkout')setTimeout(()=>{go('checkout');},60);
  if(back==='menu')setTimeout(()=>toast('Sekarang kamu sudah bisa memesan 🛍'),700);
}
function logout(){
  S.session=null;SAVE();renderAuthZone();
  toast('Kamu sudah keluar. Hati-hati di jalan 🙏');go('home',true);
}
"}

{"frame_id": "", "path": "sw2.js", "content": "/* ============ checkout, payment, orders, profile, about, admin ============ */

/* ---------- cart & checkout ---------- */
function chQty(idx,d){
  S.cart[idx].q+=d;
  if(S.cart[idx].q<=0)S.cart.splice(idx,1);
  SAVE();badgeUp();renderCheckout();
}
function chDel(i){const n=S.cart[i].n;S.cart.splice(i,1);SAVE();badgeUp();renderCheckout();toast(n+' dikeluarkan dari keranjang')}
function cartRows(){
  if(!S.cart.length)return `<div class="empty"><span class="em">🛍️</span><b>Keranjang masih kosong</b>Yuk pilih menu sedep favoritmu dulu.<br><button class="btn btn-p btn-s" style="margin-top:14px" onclick="go('menu')">Lihat menu →</button></div>`;
  return S.cart.map((i,ix)=>`<div class="cr">
    <div class="crimg">${i.em}</div>
    <div class="crinfo"><b>${i.n}</b>
      <div class="v">🌶 ${i.spice}${i.addon!=='Tanpa tambahan'?' · '+i.addon.split(' +')[0]:''}</div>
      <div class="p">${money(linePrice(i)*i.q)}</div></div>
    <div class="stepper sm"><button onclick="chQty(${ix},-1)">−</button><span>${i.q}</span><button onclick="chQty(${ix},1)">+</button></div>
    <button class="crx" onclick="chDel(${ix})">✕</button></div>`).join('');
}
function renderCheckout(){
  const s=subTotal(),d=discAmt(s),sh=shipOf(s),tot=s-d+sh;
  $('#checkoutBody').innerHTML=`<div>
    <div class="card pad" style="margin-bottom:16px">
      <div class="step"><span class="stepno">1</span><div><h4>Daftar pesanan (${cartCount()} item)</h4><p>Atur jumlah porsi sesuai selera kalian.</p></div></div>
      ${cartRows()}</div>
    <div class="card pad">
      <div class="step"><span class="stepno">2</span><div><h4>Detail pengiriman</h4><p>Kami antar hangat sampai depan pintu.</p></div></div>
      <div class="two">
        <div class="field"><label>Nama penerima</label><input class="inp" id="cName" value="${S.session?S.session.name:''}"></div>
        <div class="field"><label>No. WhatsApp</label><input class="inp" id="cPhone" value="${S.session?S.session.phone:''}"></div>
      </div>
      <div class="field"><label>Alamat pengiriman</label><textarea class="ta" id="cAddr">${S.session?S.session.addr:''}</textarea></div>
      <div class="two">
        <div class="field"><label>Waktu terima</label><select class="sel" style="width:100%"><option>Antar secepatnya (20–35 mnt)</option><option>Pilih waktu sendiri</option><option>Ambil di tempat (pickup)</option></select></div>
        <div class="field"><label>Pesan untuk dapur</label><input class="inp" id="cNote" placeholder="cth: sambal dipisah, ya"></div>
      </div></div></div>

    <div class="summarycol sticky">
      <div class="card pad">
        <h3 class="jk" style="font-size:15px;margin-bottom:6px">Ringkasan belanja</h3>
        <div class="voucher"><input id="vCode" placeholder="Kode voucher" value="${S.voucher||''}"><button class="btn btn-o btn-s" onclick="applyVoucher()">Pakai</button></div>
        <div class="paysum"><span>Subtotal</span><b>${money(s)}</b></div>
        ${d?`<div class="paysum"><span>Diskon (${S.voucher})</span><b class="disc">−${money(d)}</b></div>`:''}
        <div class="paysum"><span>Ongkos kirim</span><b>${sh?money(sh):'<span class="disc">Gratis</span>'}</b></div>
        ${s&&s<FREELIM?`<div class="trust" style="margin:10px 0"><i>🛵</i>Tambah <b>${money(FREELIM-s)}</b> lagi biar ongkirnya gratis!</div>`:''}
        <div class="paysum tot"><span>Total</span><span>${money(tot)}</span></div>
        <button class="btn btn-p btn-f" style="margin-top:14px" ${S.cart.length?'':'disabled'} onclick="go('payment')">Lanjut ke pembayaran →</button>
        <div class="trust"><i>🔒</i>Transaksi simulasi aman. Data tidak dikirim ke server mana pun pada prototype ini.</div>
      </div></div>`;
}
function applyVoucher(){
  const c=$('#vCode').value.trim().toUpperCase();
  if(!c)return toast('Ketik kode voucher dulu ya 🎟️');
  if(!VOUCH[c])return toast('Kode voucher tidak ditemukan 😢');
  S.voucher=c;renderCheckout();toast(`Voucher ${c} terpakai! Diskon ${VOUCH[c]}% 🎉`);
}

/* ---------- payment ---------- */
const PAYS=[
{k:'QRIS',ic:'▦',n:'QRIS',d:'Scan dari GoPay, OVO, DANA, m-banking'},
{k:'Transfer Bank',ic:'🏦',n:'Transfer bank',d:'BCA · Mandiri · BNI · BRI'},
{k:'E-wallet',ic:'📱',n:'E-wallet',d:'GoPay · OVO · DANA · ShopeePay'},
{k:'Kartu',ic:'💳',n:'Kartu debit/kredit',d:'Visa & Mastercard tersimpan'},
{k:'COD',ic:'💵',n:'Bayar di tempat',d:'Tunai saat pesanan tiba'},
{k:'VA',ic:'🧾',n:'Virtual account',d:'Kode unik per transaksi'}];
function renderPayment(){
  if(!S.cart.length){go('checkout');return}
  const s=subTotal(),tot=s-discAmt(s)+shipOf(s);
  $('#payBody').innerHTML=`<div class="checkout">
    <div class="card pad">
      <div class="step"><span class="stepno">3</span><div><h4>Pilih metode pembayaran</h4><p>Total ${money(tot)} · ${cartCount()} item</p></div></div>
      <div class="paym">${PAYS.map(p=>`<button class="pm ${S.pay===p.k?'on':''}" onclick="pickPay('${p.k}')">
        <span class="ic">${p.ic}</span><span><b>${p.n}</b><small>${p.d}</small></span></button>`).join('')}</div>
      ${S.pay==='QRIS'?qrBlock(tot):S.pay==='Transfer Bank'?vaBlock('BCA 8890-2163-77','a.n.':S.pay==='VA'?vaBlock('9880 7712 3344 55','PT Sedep Wetan Rasa'):S.pay==='Kartu'?cardBlock():S.pay==='E-wallet'?ewalletBlock():codBlock()}
    </div>
    <div class="summarycol sticky"><div class="card pad">
      <h3 class="jk" style="font-size:15px">Konfirmasi pesanan</h3>
      ${S.cart.map(i=>`<div class="paysum"><span>${i.em} ${i.n} ×${i.q}</span><b>${money(linePrice(i)*i.q)}</b></div>`).join('')}
      <div class="paysum" style="border-top:1px dashed var(--line-d);padding-top:10px"><span>Subtotal</span><b>${money(s)}</b></div>
      ${discAmt(s)?`<div class="paysum"><span>Diskon</span><b class="disc">−${money(discAmt(s))}</b></div>`:''}
      <div class="paysum"><span>Ongkir</span><b>${shipOf(s)?money(shipOf(s)):'Gratis'}</b></div>
      <div class="paysum tot"><span>Bayar</span><span>${money(tot)}</span></div>
      <button class="btn btn-p btn-f" style="margin-top:14px" onclick="payNow()">Bayar sekarang ✓</button>
      <button class="btn btn-o btn-f btn-s" style="margin-top:8px" onclick="go('checkout')">← Ubah pesanan</button>
    </div></div></div>`;
}
function qrBlock(t){return `<div class="qr"><div class="qrbox">${QR_SVG}</div>
  <b class="jk">Pindai untuk bayar ${money(t)}</b>
  <p class="small" style="color:#D9C4B6;margin-top:6px">BRIS / GoPay / OVO / DANA · aktif 15:00 menit</p></div>`}
function vaBlock(no,nm){return `<div class="qr" style="text-align:left"><small style="letter-spacing:1.4px;font-size:10px;color:#D9C4B6">NOMOR REKENING VIRTUAL</small>
  <div style="display:flex;align-items:center;justify-content:space-between;margin-top:8px"><b class="jk" style="font-size:20px;letter-spacing:1px">${no}</b>
  <button class="btn btn-a btn-s" onclick="toast('Nomor disalin 📋')">Salin</button></div>
  <p class="small" style="color:#D9C4B6;margin-top:10px">Atas nama: <b style="color:#fff">${nm}</b> · Transfer sesuai nominal persis agar otomatis terverifikasi.</p></div>`}
function cardBlock(){return `<div style="margin-top:14px"><div class="two"><div class="field"><label>Nomor kartu</label><input class="inp" placeholder="0000 0000 0000 0000" value="4821 •••• •••• 3390"></div><div class="field"><label>Exp / CVV</label><input class="inp" placeholder="12/28 · 123"></div></div><div class="field"><label>Nama pada kartu</label><input class="inp" placeholder="${S.session?S.session.name:''}"></div></div>`}
function ewalletBlock(){return `<div style="margin-top:14px"><div class="field"><label>Nomor e-wallet</label><input class="inp" placeholder="08xxxxxxxxxx" value="${S.session?S.session.phone:''}"></div>
  <div class="chips">${['GoPay','OVO','DANA','ShopeePay'].map((e,i)=>`<button class="chip ${i?'':'on'}">${e}</button>`).join('')}</div></div>`}
function codBlock(){return `<div class="trust" style="margin-top:14px"><i>💵</i>Siapkan uang pas sebesar total pesanan. Kurir kami membawa QRIS cadangan bila perlu.</div>`}
function pickPay(k){S.pay=k;renderPayment()}
const QR_SVG='<svg viewBox="0 0 33 33" shape-rendering="crispEdges"><rect width="33" height="33" fill="#fff"/><path fill="#3F2A20" d="M1 1h7v7H1zm1 1h5v5H2zm2 1v3h1V3zM24 1h7v7h-7zm1 1h5v5h-5zm2 1v3h1V3zM1 24h7v7H1zm1 1h5v5H2zm2 1v3h1v-3zM10 1h1v1h-1zm2 0h1v2h-1zm2 1h2v1h-2zm3 0h1v2h-1zm-9 2h1v1H8zm11 0h1v2h-1zm2 1h2v1h-2zm-9 1h1v2h-1zm12 0h1v1h-1zm-5 2h1v2h-1zm3 0h2v1h-2zm-9 1h2v1h-2zm13 0h1v2h-1zM2 10h1v1H2zm2 0h1v2H4zm10 1h1v1h-1zm3 0h1v1h-1zm7 0h1v2h-1zm3 0h1v1h-1zm-23 2h1v2H4zm14 0h2v1h-2zm4 1h1v1h-1zm5 0h2v1h-2zm-18 1h1v2H9zm12 1h1v1h-1zm5 0h1v2h-1zm3 0h1v1h-1zM3 18h2v1H3zm5 0h1v1H8zm4 0h1v2h-1zm5 0h1v1h-1zm4 1h2v1h-2zm5 0h1v1h-1zm-19 2h1v1H7zm5 0h2v1h-2zm5 0h1v1h-1zm6 0h1v2h-1zm4 0h2v1h-2zm-16 2h1v1h-1zm4 0h1v2h-1zm6 0h2v1h-2zm5 0h1v1h-1zm4 0h1v2h-1zm-13 1h1v2h-1zm5 1h2v1h-2zm6 0h1v1h-1zm4 0h2v1h-2z"/></svg>';

/* ---------- place order & status ---------- */
function payNow(){
  const s=subTotal(),tot=s-discAmt(s)+shipOf(s);
  const now=new Date();
  const o={code:'SW'+now.getTime().toString().slice(-6),
    date:now.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}),
    time:now.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'}),
    items:S.cart.map(i=>({em:i.em,n:i.n,q:i.q,price:linePrice(i)})),
    pay:S.pay,total:tot,status:'Dimasak',step:1,rated:false,eta:'25–35 menit',note:($('#cNote')&&$('#cNote').value)||''};
  S.orders.unshift(o);S.cart=[];S.voucher=null;SAVE();badgeUp();
  S.draft=o;
  toast('Pembayaran berhasil! Dapur mulai mengolah pesananmu 🔥');
  go('orders');
}
const STEPS=[['📥','Pesanan diterima','Kami meneruskan pesananmu langsung ke dapur.'],['🔥','Sedang dimasak','Chef meracik bumbu dan membakar di arang.'],['','Dikemas hangat','Dikemas kedap agar rasa dan suhu terjaga.'],['🛵','Diantar kurir','Kurir kami meluncur ke alamatmu.'],['✅','Pesanan tiba','Silakan nikmati selagi hangat!']];
function renderOrders(){
  const act=S.orders.filter(o=>o.status!=='Selesai');
  const done=S.orders.filter(o=>o.status==='Selesai');
  $('#ordersBody').innerHTML=(S.orders.length?'':`<div class="card pad"><div class="empty"><span class="em">◷</span><b>Belum ada pesanan</b>Pesanan pertamamu akan muncul di sini.<br><button class="btn btn-p btn-s" style="margin-top:14px" onclick="go('menu')">Mulai pesan →</button></div></div>`)
  +act.map(o=>trackCard(o)).join('')
  +(done.length?`<div class="sec-h"><div><span class="eyebrow">🧾 Riwayat</span><h2>Pembelian sebelumnya</h2></div></div>`+done.map(o=>histRow(o)).join(''):'');
}
function trackCard(o){
  const cls=o.step>=4?'done':o.step>=1?'cook':'proc';
  return `<div class="card pad" style="margin-bottom:16px">
    <div class="ordhead"><div><span class="eyebrow">${o.status==='Dimasak'?'🔥 Sedang dikerjakan':'✅ Siap dinikmati'}</span><h3>${o.code}</h3>
      <p class="muted small" style="margin-top:4px">${o.date} · ${o.time} WIB · ${o.pay} · ${o.eta}</p></div>
      <span class="pill ${cls}">${o.status==='Dimasak'?'● Dimasak':'● Tiba'}</span></div>
    <div class="ordgrid">
      <div class="ocell"><small>Diantar oleh</small><b>Rudi W.</b></div>
      <div class="ocell"><small>Metode bayar</small><b>${o.pay} · Lunas</b></div>
      <div class="ocell"><small>Total dibayar</small><b style="color:var(--brick)">${money(o.total)}</b></div></div>
    <div class="two"><div><div class="opttl" style="margin-top:0">Lacak pesanan</div>
      <div class="track">${STEPS.map((st,i)=>`<div class="tstep ${i<o.step?'done':i===o.step?'now':''}">
        <span class="tdot">${i<o.step?'✓':i===o.step?'●':''}</span><b>${st[1]}</b><p>${st[0]} ${st[2]}</p></div>`).join('')}</div></div>
      <div><div class="opttl" style="margin-top:0">Item pesanan</div>
      ${o.items.map(i=>`<div class="hr" style="border:1px solid var(--line);margin-bottom:8px;padding:11px"><div class="hrimg">${i.em}</div><div class="hrinfo"><b>${i.n}</b><p>${money(i.price)} × ${i.q}</p></div><b style="color:var(--brick);font-size:12.5px">${money(i.price*i.q)}</b></div>`).join('')}
      <button class="btn btn-o btn-f btn-s" style="margin-top:6px" onclick="advance('${o.code}')">▶ Simulasi: majukan status</button></div></div></div>`;
}
function advance(code){
  const o=S.orders.find(x=>x.code===code);
  if(o.step<4)o.step++;
  if(o.step>=4){o.status='Selesai';toast('Pesanan tiba! Selamat menikmati 🍽️')}else toast('Status diperbarui: '+STEPS[o.step][1]);
  SAVE();renderOrders();
}
function histRow(o){
  return `<div class="hr"><div class="hrimg">🧾</div>
    <div class="hrinfo"><b>${o.code} · ${o.pay}</b><p>${o.items.map(i=>`${i.em} ${i.n} ×${i.q}`).join(' · ')}</p>
      <small>${o.date} ${o.time} WIB</small></div>
    <span class="pill ${o.status==='Selesai'?'done':'unpaid'}">${o.status}</span>
    <div class="hrright"><b>${money(o.total)}</b><br><button class="btn btn-o btn-s" style="margin-top:7px" onclick="reorder('${o.code}')">Pesan lagi</button></div></div>`;
}
function reorder(code){
  const o=S.orders.find(x=>x.code===code);
  o.items.forEach(it=>{
    const f=S.menu.find(m=>m.n===it.n);
    if(f)S.cart.push({id:f.id,n:f.n,em:f.em,price:f.price,q:it.q,spice:'Sedang',addon:'Tanpa tambahan'});
  });
  SAVE();badgeUp();toast('Item di salin ulang ke keranjang 🔁');go('checkout');
}
function rateOrder(code){
  const o=S.orders.find(x=>x.code===code);o.rated=true;SAVE();renderOrders();toast('Makasih ulasannya! ⭐⭐⭐⭐⭐');
}

