}

/* ---------- footer ---------- */
function renderFoot(){
  $('#foot').innerHTML=`<div class="wrap"><div class="footgrid">
    <div><div class="brand"><span class="logo" data-logo></span><span class="brandtxt"><b>sedep wetan</b><small style="color:#9C8578">Rasa rumahan, bikin kangen</small></span></div>
      <p>Rumah makan masakan Indonesia yang berdiri sejak 1998. Kini bisa dipesan daring, diantar hangat dari dapur kami ke meja kamu.</p>
      <div class="soc"><button onclick="toast('Instagram @sedepwetan 📸')">◎</button><button onclick="toast('WhatsApp 0812-3456-7890 💬')"></button><button onclick="toast('TikTok @sedepwetan 🎵')">♪</button></div></div>
    <div><h5>Jelajahi</h5><div class="fl">
      <button onclick="go('menu')">Semua menu</button><button onclick="go('menu');S.cat='Makanan Berat';renderMenu()">Makanan berat</button>
      <button onclick="go('menu');S.cat='Camilan';renderMenu()">Camilan</button><button onclick="go('menu');S.cat='Minuman';renderMenu()">Minuman</button></div></div>
    <div><h5>Akun</h5><div class="fl">
      <button onclick="openCart()">Keranjang</button><button onclick="loggedIn()?go('orders'):requireLogin('orders')">Pesanan saya</button>
      <button onclick="loggedIn()?go('profile'):requireLogin('profile')">Profil</button><button onclick="go('admin',true)">Admin</button></div></div>
    <div><h5>Kontak & jam buka</h5><div class="fl">
      <button onclick="go('about')">Jl. Monumen Jogja Kembali No. 129</button><button onclick="toast('Telepon 0812-3456-7890 📞')">0812-3456-7890</button>
      <button onclick="toast('Email halo@sedepwetan.id ✉️')">halo@sedepwetan.id</button><button>Setiap hari · 09.00–22.00 WIB</button></div></div>
  </div><div class="fbot"><span>© 2025 Sedep Wetan. Prototype UI/UX — data simulasi, tanpa backend.</span>
    <span>Dibuat dengan 🌿 &amp; gula aren sejati.</span></div></div>`;
}

/* ---------- boot ---------- */
function boot(){
  $$('[data-logo]').forEach(e=>e.innerHTML=LEAF);
  const msgs=['Menyiapkan dapur...','Merebus kaldu ayam kampung...','Membakar ayam di arang...','Menyusun lalapan segar...','Hampir siap, santai dulu ☕'];
  let mi=0;const iv=setInterval(()=>{$('#ldmsg').textContent=msgs[mi++%msgs.length]},520);
  renderAuthZone();renderFoot();renderHome();badgeUp();renderCats();renderMenu();
  $('#q').addEventListener('input',e=>{S.q=e.target.value;renderMenu()});
  $('#sortSel').addEventListener('change',e=>{S.sort=e.target.value;renderMenu()});
  $$('#nav button,#mobnav button').forEach(b=>b.addEventListener('click',()=>go(b.dataset.v)));
  setTimeout(()=>{clearInterval(iv);$('#loading').classList.add('hide')},2300);
}
boot();
"}

