    '<span class="pill ' + cls + '">' + (o.status === 'Dimasak' ? '● Dimasak' : '● Tiba') + '</span></div>' +
    cells + '<div class="two"><div><div class="opttl" style="margin-top:0">Lacak pesanan</div>' +
    '<div class="track">' + track + '</div></div><div><div class="opttl" style="margin-top:0">Item pesanan</div>' +
    items + '<button class="btn btn-o btn-f btn-s" style="margin-top:6px" onclick="advance(\'' + o.code + '\')">▶ Simulasi: majukan status</button>' +
    '</div></div></div>';
