{"content": "/* ============================================================
   SEDEP WETAN — Kueri Supabase (TEMPLATE)
   Ganti fungsi data dummy di sw.js dengan fungsi di bawah ini
   saat backend sudah tersambung. Semua fungsi async: pakai await.
   ============================================================ */

/* ---------- MENU ----------
   Dipakai renderMenu(), renderHome() (rail favorit), detail produk.
*/
async function fetchMenu() {
  const { data, error } = await sb
    .from('menu_items')
    .select('*, categories(name, icon)')
    .eq('is_active', true)
    .order('sold_count', { ascending: false });
  if (error) throw error;
  // Bentuk ulang ke struktur yang dipakai UI:
  return data.map(m => ({
    id: m.id,
    n: m.name,
    cat: m.categories?.name || 'Makanan Berat',
    em: m.image_url ? '' : '🍽️',   // ganti <img src=...> bila pakai gambar
    img: m.image_url,
    price: Number(m.price),
    old: Number(m.compare_at_price),
    rate: Number(m.rating),
    sold: m.sold_count,
    badge: m.badge,
    fav: m.is_favorite,
    desc: m.description,
    long: m.long_description,
    tags: m.spice_level === 'Pedas' ? ['Pedas'] : [],
    on: m.is_active
  }));
}

async function fetchCategories() {
  const { data, error } = await sb.from('categories').select('*').order('sort_order');
  if (error) throw error;
  return data;
}

/* ---------- ADMIN: CRUD menu ---------- */
async function adminCreateMenu(item) {
  const { data, error } = await sb.from('menu_items').insert(item).select().single();
  if (error) throw error;
  return data;
}

async function adminUpdateMenu(id, patch) {
  // patch contoh: { price: 30000, is_active: false }
  const { data, error } = await sb.from('menu_items').update(patch).eq('id', id).select().single();
  if (error) throw error;
  return data;
}

async function adminDeleteMenu(id) {
  const { error } = await sb.from('menu_items').delete().eq('id', id);
  if (error) throw error;
}

/* Upload gambar menu ke Storage (bucket 'menu'), lalu simpan URL-nya. */
async function uploadMenuImage(file) {
  const path = `${Date.now()}-${file.name}`;
  const { error: upErr } = await sb.storage
    .from(SUPABASE_CONFIG.storageBucket)
    .upload(path, file, { cacheControl: '3600', upsert: false });
  if (upErr) throw upErr;
  const { data } = sb.storage.from(SUPABASE_CONFIG.storageBucket).getPublicUrl(path);
  return data.publicUrl;
}

/* ---------- CHECKOUT: buat pesanan ----------
   Satu transaksi: orders + order_items. Harga diambil dari DB (server-side truth),
   jangan percaya total dari client. Untuk keamanan maksimal pindahkan ke Edge Function.
*/
async function createOrder({ cart, shipping, promoCode, recipient, note, method }) {
  const { data: user } = await sb.auth.getUser();
  let subtotal = 0;
  const items = [];
  for (const line of cart) {
    const { data: m, error } = await sb.from('menu_items').select('name, price, image_url').eq('id', line.id).single();
    if (error) throw error;
    const unit = Number(m.price) + (line.addonPrice || 0);
    subtotal += unit * line.q;
    items.push({
      menu_item_id: m.id, menu_name: m.name, image_url: m.image_url,
      unit_price: unit, quantity: line.q, spice_level: line.spice,
      addon: line.addon, line_total: unit * line.q, menu_emoji: line.em
    });
  }
  const { data: promo } = promoCode ? await sb.from('promos')
    .select('discount_percent').eq('code', promoCode).eq('is_active', true).single() : { data: null };
  const discount = promo ? Math.round(subtotal * Number(promo.discount_percent) / 100) : 0;
  const orderNo = 'SW' + Date.now().toString().slice(-6);

  const { data: order, error } = await sb.from('orders').insert({
    order_code: orderNo,
    user_id: user.id,
    recipient_name: recipient.name,
    recipient_phone: recipient.phone,
    address: recipient.address,
    note,
    method,
    subtotal, discount, shipping_fee: shipping,
    grand_total: subtotal - discount + shipping,
    promo_code: promoCode || null,
    payment_status: method === 'COD' ? 'pending' : 'paid',   // TODO: sesuaikan dengan gateway (Midtrans/Xendit)
    order_status: 'Baru'
  }).select().single();
  if (error) throw error;

  const rows = items.map(i => ({ ...i, order_id: order.id }));
  const { error: err2 } = await sb.from('order_items').insert(rows);
  if (err2) throw err2;
  return order;
}

/* ---------- RIWAYAT & STATUS PESANAN ---------- */
async function fetchMyOrders() {
  const { data: user } = await sb.auth.getUser();
  const { data, error } = await sb
    .from('orders')
    .select('*, order_items(*)')
    .eq('user_id', user.id)
    .order('created_at', { ascending: false });
  if (error) throw error;
  return data;
}

/* Pembaruan status realtime (untuk halaman Lacak Pesanan). */
function subscribeOrder(orderId, cb) {
  return sb
    .channel('order-' + orderId)
    .on('postgres_changes',
      { event: 'UPDATE', schema: 'public', table: 'orders', filter: 'id=eq.' + orderId },
      payload => cb(payload.new))
    .subscribe();
}

/* ---------- ADMIN: laporan ---------- */
async function fetchSalesDaily(days = 7) {
  const { data, error } = await sb.from('v_sales_daily').select('*').limit(days);
  if (error) throw error;
  return data;
}

async function fetchTopProducts() {
  const { data, error } = await sb.from('v_top_products').limit(6);
  if (error) throw error;
  return data;
}

async function fetchAllOrdersForAdmin(status) {
  let q = sb.from('orders').select('*, order_items(*)').order('created_at', { ascending: false }).limit(100);
  if (status && status !== 'Semua') q = q.eq('order_status', status);
  const { data, error } = await q;
  if (error) throw error;
  return data;
}

async function adminUpdateOrderStatus(id, orderStatus) {
  const { data, error } = await sb.from('orders')
    .update({ order_status: orderStatus }).eq('id', id).select().single();
  if (error) throw error;
  return data;
}

/* ---------- PROFIL ---------- */
async function fetchProfile() {
  const { data: user } = await sb.auth.getUser();
  const { data, error } = await sb.from('profiles').select('*').eq('id', user.id).single();
  if (error) throw error;
  return data;
}

async function updateProfile(patch) {
  const { data: user } = await sb.auth.getUser();
  const { data, error } = await sb.from('profiles').update(patch).eq('id', user.id).select().single();
  if (error) throw error;
  return data;
}
